style.css:
@-moz-document domain("roblox.com") {
/* === CHANGE THIS URL TO YOUR IMAGE === */
    :root {
        --roblox-bg-url: url("https://i.imgur.com/ZxDY4zw.jpeg"); /* Replace with your image URL */
    }

    /* Homepage and Profile Background */
    body, html, .rbx-page, .rbx-page-wrapper, .rbx-page-content {
        background: none !important;
        background-image: var(--roblox-bg-url) !important;
        background-size: cover !important;
        background-position: center center !important;
        background-attachment: fixed !important;
    }

    /* Login and Signup Pages */
    .rbx-login-form, .rbx-signup-form {
        background: transparent !important;
    }

    /* Modals and Popups */
    .rbx-modal, .rbx-popup {
        background-color: transparent !important;
    }

    /* Navbar */
    .rbx-navbar {
        background-color: rgba(255, 255, 255, 0.9) !important;
        backdrop-filter: blur(2px);
    }

    /* Footer */
    .rbx-footer {
        background-color: rgba(255, 255, 255, 0.9) !important;
        backdrop-filter: blur(2px);
    }

    /* Profile Header */
    .rbx-profile-header {
        background: none !important;
    }

    /* Profile Content */
    .rbx-profile-content {
        background: transparent !important;
    }

    /* Game Cards */
    .rbx-game-card {
        background-color: transparent !important;
    }

    /* Sections */
    .rbx-section {
        background-color: transparent !important;
    }
}
